.rfq-access-instructions {
    background-color: #fafafa; /* Consistent with .mt-table-container background */
    -webkit-border-radius: 8px;
       -moz-border-radius: 8px;
            border-radius: 8px;      /* Consistent with .mt-table-container border-radius */
    padding: 20px 25px;      /* Similar to .mt-totals-summary padding */
    margin-top: 20px;        /* Spacing before the block */
    margin-bottom: 25px;     /* Spacing after the block */
    border: 1px solid #e0e0e0; /* Subtle border, similar to .mt-totals-divider */
    page-break-inside: avoid; /* Try to keep the block from splitting across pages */
}

.rfq-access-instructions .rfq-access-title {
    font-size: 1.125rem; /* From .text-level-3 */
    font-weight: 600;    /* From .text-level-3 */
    color: #171717;      /* Strong heading color, like .mt-table-container caption or .mt-totals-item.mt-grand-total .mt-totals-label */
    margin-top: 0;
    margin-bottom: 12px;
}

.rfq-access-instructions .rfq-access-text {
    font-size: 0.875rem; /* From .text-level-1 */
    color: #555;         /* Standard paragraph color, like .mt-table-container tbody td or .mt-payment-info-internal p */
    line-height: 1.6;    /* Good readability, similar to .arabic-text or .mt-payment-info-internal p */
    margin-bottom: 18px;
}

.rfq-access-instructions .rfq-access-link-section {
    margin-bottom: 18px;
    line-height: 1.5; /* Ensure good spacing if label and link wrap */
}

.rfq-access-instructions .rfq-access-label {
    font-size: 0.875rem; /* From .text-level-1 */
    font-weight: 600;    /* Make label slightly stronger, like .mt-payment-payable-to (but using text-level-1 size) */
    color: #333;         /* Darker than paragraph text, like .mt-payment-info-internal .mt-iban-number or .mt-totals-summary color */
    margin-right: 8px;
}

.rfq-access-instructions .rfq-access-link {
    font-size: 0.875rem; /* From .text-level-1 */
    color: #B58B0F;      /* Using accent color from .mt-totals-item.mt-grand-total .mt-totals-value */
    text-decoration: underline;
    font-weight: 500;    /* Slightly bolder than normal text */
}

.rfq-access-instructions .rfq-access-link:hover {
    color: #8c6c0b; /* Darker shade of the accent color for hover */
    text-decoration: none;
}

.rfq-access-instructions .rfq-access-qrcode-section .rfq-access-label {
    display: block; /* Makes the label appear on its own line above the QR code */
    margin-bottom: 8px;
}

.rfq-access-instructions .rfq-access-qrcode-image {
    width: 150px;              /* Desired width of the QR code image */
    height: 150px;             /* Desired height of the QR code image */
    border: 1px solid #e0e0e0; /* Light border around QR, like .mt-totals-divider */
    padding: 5px;              /* Padding inside border before QR image itself */
    background-color: #ffffff; /* White background for the QR code image */
    display: block;            /* Ensures it takes up its own line and respects margin */
}

